-- Brismart product catalogue (generated by tools/make_seed.py). Run after schema.sql.
-- Safe to re-run: existing products with the same id are updated.
on conflict (id) do update set cat = excluded.cat, name = excluded.name, bn = excluded.bn, brand = excluded.brand, size = excluded.size, price = excluded.price, price_max = excluded.price_max, price_unit = excluded.price_unit, img = excluded.img, icon = excluded.icon, note = excluded.note;
